// SOAL 3: MENGUBAH ELEMEN ARRAY

const nilaiSiswa = [75, 80, 65, 90, 85];

// 1. Mengubah nilai kedua menjadi 88
nilaiSiswa[1] = 88;

// 2. Mengubah nilai ketiga menjadi 78
nilaiSiswa[2] = 78;

// 3. Menampilkan seluruh Array
console.log("Nilai setelah diubah:", nilaiSiswa);

// 4. Menampilkan nilai pertama dan terakhir
console.log("Nilai pertama:", nilaiSiswa[0]);
console.log("Nilai terakhir:", nilaiSiswa[4]);